INSERT INTO site_settings (id, site_title_vi, site_description_vi, seo_keywords_vi, og_image_url, twitter_handle, github_url, linkedin_url, email, created_at, updated_at, site_title_en, site_description_en, seo_keywords_en, resume_url, phone) VALUES (1, 'Trần Minh Hiểu | AI Software Engineer', 'Kỹ sư Khoa học Máy tính kết hợp nền tảng AI/ML/DL chuyên sâu với tư duy kỹ thuật phần mềm vững chắc — tập trung nghiên cứu và hiện thực hóa các giải pháp AI cùng công nghệ phân tán (Blockchain/Web3) vào giải quyết bài toán thực tế.', 'Trần Minh Hiểu,Tran Minh Hieu,AI Software Engineer,Applied AI Researcher,Graph Neural Networks,Representation Learning,Advanced RAG,Hybrid Search,FastAPI,PyTorch Geometric,Python,Portfolio', '', '', 'https://github.com/Tmh3101', 'https://linkedin.com/in/tmh3101', 'hieutm.site@gmail.com', '2026-03-15T17:03:18.365486+00:00', '2026-09-30T18:15:35.795421+00:00', 'Tran Minh Hieu | AI Software Engineer', 'Engineer in Computer Science combining a solid foundation in AI/ML/DL with robust software engineering — focused on researching and integrating AI solutions and decentralized technologies (Blockchain/Web3) to solve real-world problems.', 'Tran Minh Hieu,AI Software Engineer,Applied AI Researcher,Graph Neural Networks,Representation Learning,Advanced RAG,Hybrid Search,FastAPI,PyTorch Geometric,Python,Portfolio', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', NULL);
INSERT INTO hero_section (id, greeting_vi, name, headline_vi, subheadline_vi, roles_vi, avatar_url, cta_primary_label_vi, cta_primary_href, cta_secondary_label_vi, cta_secondary_href, created_at, updated_at, greeting_en, headline_en, subheadline_en, roles_en, cta_primary_label_en, cta_secondary_label_en, subtitle_vi, subtitle_en, role1_label_vi, role1_label_en, role2_label_vi, role2_label_en, role3_label_vi, role3_label_en) VALUES (1, 'Xin chào, tôi là', 'Trần Minh Hiểu', 'AI Software Engineer', 'Kỹ sư Khoa học Máy tính kết hợp nền tảng AI/ML/DL chuyên sâu với tư duy kỹ thuật phần mềm vững chắc — tập trung nghiên cứu và hiện thực hóa các giải pháp AI cùng công nghệ phân tán (Blockchain/Web3) vào giải quyết bài toán thực tế.', 'AI / Software,Đại học Cần Thơ,Khoa học máy tính,1 năm', '/avatars/hieutm.jpg', 'Xem CV', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', 'Liên hệ', '#contact', '2026-03-15T17:07:04.237823+00:00', '2026-09-30T18:15:35.441032+00:00', 'Hi, I am', 'AI Software Engineer', 'Engineer in Computer Science combining a solid foundation in AI/ML/DL with robust software engineering — focused on researching and integrating AI solutions and decentralized technologies (Blockchain/Web3) to solve real-world problems.', 'AI / Software,Can Tho University,Computer Science,1 year', NULL, NULL, 'Software Engineering & Applied AI', 'Software Engineering & Applied AI', 'Tập trung', 'Focus', 'Tốt nghiệp', 'Graduated', 'Chuyên ngành', 'Major');
INSERT INTO experience_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, current_role_label_vi, current_role_label_en, earlier_roles_label_vi, earlier_roles_label_en, earlier_roles_copy_vi, earlier_roles_copy_en, education_label_vi, education_label_en, highlights_label_vi, highlights_label_en, created_at, updated_at) VALUES (1, 'Hành trình', 'Journey', 'Kinh nghiệm', 'Professional', 'làm việc', 'Experience', 'Hành trình từ khi còn là sinh viên đến khi trở thành Backend Developer, tập trung vào việc xây dựng các hệ thống ổn định và có khả năng mở rộng.', 'A journey from student years to Backend Developer, focusing on building stable and scalable systems.', 'Vai trò hiện tại', 'Current role', 'Các chặng trước', 'Earlier roles', 'Những vai trò trước đó tạo nền cho cách tôi xây backend systems hôm nay.', 'The earlier roles that shaped how I approach backend systems today.', 'Học vấn', 'Education', 'Điểm chính', 'Highlights', '2026-03-17T07:48:51.662793+00:00', '2026-03-17T07:48:51.662793+00:00');
INSERT INTO skill_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, created_at, updated_at) VALUES (1, 'SKILLS', 'SKILLS', 'Kỹ năng Chuyên môn &', 'Technical &', 'Kỹ năng mềm', 'Soft Skills', 'Tổng hòa giữa bộ khả năng kỹ thuật và phương pháp làm việc chuẩn mực.', 'A synthesis of technical capabilities and disciplined engineering methodologies.', '2026-03-17T06:15:44.607856+00:00', '2026-10-01T08:40:23.344058+00:00');
INSERT INTO approach_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, note_label_vi, note_label_en, note_vi, note_en, created_at, updated_at) VALUES (1, 'ABOUT ME', 'ABOUT ME', 'Kiến trúc Hệ thống &', 'Software Systems &', 'Nền tảng AI Ứng dụng', 'Applied AI', 'Tốt nghiệp Kỹ sư Khoa học Máy tính (chuyên sâu AI) tại Đại học Cần Thơ (GPA 3.64/4.00), có nền tảng năng lực từ nghiên cứu, huấn luyện mô hình đến xây dựng phần mềm hoàn chỉnh. Đồ án tốt nghiệp SybilSignal (GNN + ML, điểm 9.8/10) và nền tảng LMS Xpervia (tích hợp RAG chatbot & ReSys).
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (2, 'Ứng dụng AI', 'APPLIED AI', 'Triển khai, tích hợp giải pháp AI và mô hình ngôn ngữ lớn (LLM) vào sản phẩm: ứng dụng các kỹ thuật RAG, xây dựng và tự động hóa luồng dữ liệu phục vụ vận hành thực tế.', '', 1, '2026-03-17T05:59:15.492065+00:00', '2026-10-01T09:56:35.658642+00:00', 'Applied AI', 'APPLIED AI', 'Deploying and integrating AI solutions and large language models (LLMs) into production: applying RAG techniques, building, and automating resilient data workflows.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (3, 'Kỹ thuật Phần mềm', 'SOFTWARE ENGINEERING', 'Thiết kế kiến trúc phân tầng chuẩn mực, type-safe API, bảo mật. Thiết kế hàng đợi tác vụ nền chịu lỗi cao và tích hợp cổng thanh toán bảo đảm tính toàn vẹn dữ liệu.', '', 2, '2026-03-17T05:59:58.41027+00:00', '2026-10-01T09:56:35.968821+00:00', 'Software Engineering', 'SOFTWARE ENGINEERING', 'Designing clean layered architectures, type-safe APIs, and robust security. Architecting fault-tolerant background queues and payment gateway integrations with strict data integrity.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (4, 'Dữ liệu & Học máy (ML/DL)', 'AI & DATA', 'Tự động hóa luồng thu thập, trích xuất và tiền xử lý dữ liệu. Thiết kế, xây dựng và huấn luyện các mô hình ML/DL giải quyết hiệu quả các bài toán dự báo, phân loại và nhận diện bất thường.', '', 3, '2026-03-17T06:00:21.343968+00:00', '2026-10-01T09:56:36.269986+00:00', 'Data & Machine Learning (ML/DL)', 'AI & DATA', 'Automating data collection, extraction, and preprocessing pipelines. Designing, building, and training ML/DL models to solve prediction, classification, and anomaly detection problems.');
INSERT INTO stats (id, label_vi, value, suffix, sort_order, created_at, updated_at, label_en, copy_vi, copy_en, icon) VALUES (1, 'GPA Kỹ sư CNTT (Loại Giỏi)', 3.64, '/4.0', 1, '2026-03-16T16:28:42.41604+00:00', '2026-09-30T16:43:56.665355+00:00', 'Honors CS Degree', 'Đại học Cần Thơ', 'Can Tho University', 'GraduationCap');
INSERT INTO stats (id, label_vi, value, suffix, sort_order, created_at, updated_at, label_en, copy_vi, copy_en, icon) VALUES (2, 'Điểm Khóa luận Tốt nghiệp', 9.8, '/10', 2, '2026-03-16T16:31:03.027016+00:00', '2026-09-30T16:43:56.853983+00:00', 'Graduation Thesis Score', 'Graph Neural Networks', 'Graph Neural Networks', 'Award');
INSERT INTO stats (id, label_vi, value, suffix, sort_order, created_at, updated_at, label_en, copy_vi, copy_en, icon) VALUES (3, 'Dự án Production & R&D', 5, '+', 3, '2026-03-16T16:32:26.179702+00:00', '2026-09-30T16:43:57.125989+00:00', 'Production & R&D Projects', 'SaaS, Distributed, AI', 'SaaS, Distributed, AI', 'Rocket');
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (3, 'vielora', 'Vielora - AI Chatbot SaaS Platform', 'Nền tảng AI Chatbot SaaS Multi-tenant & RAG Pipeline', 'Xây dựng hệ thống AI Chatbot SaaS Multi-tenant hoàn chỉnh, giúp mọi người tạo trợ lý AI 24/7 nhanh chóng. Thiết kế RAG pipeline với hybrid search (vector + full-text) sử dụng pgvector, hàng đợi tác vụ nền (Redis/BullMQ), tích hợp Google Gemini API, thanh toán tự động payOS và xuất hóa đơn điện tử EasyInvoice.', '/assets/optimized/vielora.webp', NULL, 'https://vielora.vn', 'Next.js 14,TypeScript,Supabase,pgvector,Redis,BullMQ,Docker,Gemini API', true, 0, '2026-08-16T07:51:47.579392+00:00', '2026-10-01T09:05:11.045548+00:00', 'Vielora - AI Chatbot SaaS Platform', 'Multi-tenant AI Chatbot SaaS & RAG Pipeline', 'End-to-end multi-tenant AI Chatbot SaaS platform empowering quick 24/7 AI assistant creation. Designed RAG pipeline with hybrid search (pgvector + full-text), background task queues (Redis/BullMQ), Google Gemini API integration, automated payOS checkout, and EasyInvoice VAT generation.', NULL, 'Multi-tenant,Hybrid Search,Async Queue,payOS & EasyInvoice', 'Multi-tenant,Hybrid Search,Async Queue,payOS & EasyInvoice', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (4, 'xpervia', 'Xpervia - AI LMS & Recommender Engine', 'Nền tảng quản lý học tập tích hợp RAG Assistant & Gợi ý khóa học', 'Thiết kế và xây dựng hệ thống quản lý học tập (LMS) hoàn chỉnh. Thực nghiệm đối sánh hiệu quả giữa Vanilla RAG và HyDE RAG; fine-tune mô hình ngôn ngữ mã nguồn mở Qwen2.5-1.5B trên dữ liệu bài học; xây dựng bộ gợi ý khóa học lai (Collaborative + Content-based).', '/assets/optimized/xpervia.webp', 'https://github.com/Tmh3101/xpervia', 'https://xpervia.vercel.app', 'Django,DRF,Next.js,LangChain,Qwen2.5,PostgreSQL', false, 4, '2026-08-16T07:51:47.579392+00:00', '2026-10-01T09:05:12.015025+00:00', 'Xpervia - AI LMS & Recommender Engine', 'Learning Management System & AI RAG Chatbot', 'Designed and developed a complete Learning Management System (LMS). Conducted empirical comparison between Vanilla RAG and HyDE RAG; fine-tuned open-source Qwen2.5-1.5B on lesson domain data; built hybrid course recommender (Collaborative + Content-based filtering).', NULL, 'Vanilla vs HyDE RAG,Qwen2.5-1.5B Fine-tuning,Hybrid Recommender,RBAC', 'Vanilla vs HyDE RAG,Qwen2.5-1.5B Fine-tuning,Hybrid Recommender,RBAC', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (5, 'sybilsignal', 'SybilSignal - Graph-based Risk Detection', 'Hệ thống phát hiện tài khoản bất thường trên Social Graph với mạng nơ ron đồ thị (9.8/10)', 'Trích xuất và tiền xử lý dữ liệu on-chain từ Lens Protocol với BigQuery, cấu trúc dữ liệu sang đồ thị 4 tầng. Thiết kế và thử nghiệm các kiến trúc tách rời (GATv2 + Random Forest); xây dựng dashboard Next.js + FastAPI trực quan hóa Attention Weights.', '/assets/optimized/sybilsignal.webp', 'https://github.com/Tmh3101/sybilsignal-app', 'https://sybilsignal.vercel.app', 'Python,PyTorch Geometric,FastAPI,BigQuery,Modal,Next.js', true, 2, '2026-08-16T07:51:47.579392+00:00', '2026-10-01T09:05:11.516069+00:00', 'SybilSignal - Graph-based Risk Detection', 'Graph-based Sybil Detection on Social Graphs (Thesis 9.8/10)', 'Extracted and preprocessed on-chain Lens Protocol data with BigQuery, structured into 4-layer graph. Designed and evaluated decoupled architectures (GATv2 + Random Forest); built Next.js + FastAPI dashboard visualizing Attention Weights.', NULL, 'GATv2 Graph Neural Network,Decoupled GNN-ML,XAI Attention Weights,BigQuery Pipeline', 'GATv2 Graph Neural Network,Decoupled GNN-ML,XAI Attention Weights,BigQuery Pipeline', 'https://drive.google.com/file/d/1YOmJeSeUQA0xQq--tOlI6aosKq5rHam8/view?usp=sharing');
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (6, 'slice-socialfi', 'Slice SocialFi (SliceFi) - Cross-chain Bridge', 'Cross-chain bridge & Hệ thống xử lý giao dịch an toàn', 'Thiết kế cầu nối token cross-chain giữa BNB Smart Chain và LensChain (sử dụng cơ chế Lock/Mint & Burn/Unlock). Xây dựng hàng đợi tác vụ xử lý luồng giao dịch Fiat-to-Crypto (tích hợp nạp token DNPAY) bảo đảm tính toàn vẹn dữ liệu.', '/assets/optimized/slice-socialfi.webp', NULL, 'https://slicefi.xyz/', 'Node.js,Hono,Viem,Solidity,Redis,PostgreSQL,Docker', true, 1, '2026-09-30T09:21:55.037857+00:00', '2026-10-01T09:05:11.330727+00:00', 'Slice SocialFi (SliceFi) - Cross-chain Bridge', 'Cross-chain bridge & Secure Transaction Processing System', 'Designed cross-chain token bridge between BNB Smart Chain and LensChain (using Lock/Mint & Burn/Unlock mechanism). Built task queue processing Fiat-to-Crypto transactions (integrated DNPAY token top-up) guaranteeing data integrity.', NULL, 'Cross-chain Token Bridge,Zero-data-loss Redis Queue,DNPAY Fiat-to-Crypto,AWS EC2', 'Cross-chain Token Bridge,Zero-data-loss Redis Queue,DNPAY Fiat-to-Crypto,AWS EC2', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (7, 'giftcards', 'Giftcards.vn - Corporate Gift Solutions', 'Giải pháp quà tặng doanh nghiệp', 'Tích hợp cổng thanh toán DNPAY Merchant, thiết kế cơ chế retry payment flow giảm thiểu tỷ lệ rớt đơn hàng.', '/assets/optimized/giftcards.webp', NULL, NULL, 'NestJS,MongoDB,Redis,ReactJS', false, 3, '2026-09-30T09:21:55.431521+00:00', '2026-10-01T09:05:11.675055+00:00', 'Giftcards.vn - Corporate Gift Solutions', 'Corporate Gift Solutions', 'Integrated DNPAY Merchant payment gateway, designed payment retry mechanism minimizing cart abandonment rate.', NULL, 'DNPAY Merchant Gateway,Payment Retry Flow,Order Lifecycle Management', 'DNPAY Merchant Gateway,Payment Retry Flow,Order Lifecycle Management', NULL);
